using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json.Linq;
public static class BDLightingBalance {
 static Vector3 At(Vector3[] ps,float d){for(int i=1;i<ps.Length;i++){float n=Vector3.Distance(ps[i-1],ps[i]);if(d<=n)return Vector3.Lerp(ps[i-1],ps[i],d/n);d-=n;}return ps.Last();}
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit required");string r=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));var plan=JObject.Parse(File.ReadAllText(r+"/SourceAssets/B2_FullFloor/plan.json"));var root=s.GetRootGameObjects().Single(g=>g.name=="B2_MachineryNetwork").transform.Find("B2_DetailPass/B2_ProcessLighting");int upper=0;foreach(var t in plan["tunnels"]){string id=((string)t["id"]).Split('-')[1];var ps=t["path"].Select(p=>new Vector3((float)p[0],0,-(float)p[1])).ToArray();float len=0;for(int i=1;i<ps.Length;i++)len+=Vector3.Distance(ps[i-1],ps[i]);var fixtures=root.Cast<Transform>().Where(x=>x.name.StartsWith("B2_"+id+"_PipeBulkhead_")).OrderBy(x=>int.Parse(x.name.Split('_').Last())).ToArray();for(int i=0;i<fixtures.Length;i++){float d=len*(i+.5f)/fixtures.Length;bool high=id!="T04"&&id!="T06"&&i%2==0;var dir=(At(ps,d+.04f)-At(ps,d-.04f)).normalized;var right=Vector3.Cross(Vector3.up,dir);int sign=i%2==0?1:-1;var outward=(right*sign*(high?1f:2.31f)+Vector3.up*(high?1f:.60f)).normalized;fixtures[i].localPosition=At(ps,d)+Vector3.up*1.35f+outward*2.40f;fixtures[i].localRotation=Quaternion.LookRotation(-outward);fixtures[i].GetComponentInChildren<Light>().intensity=high?1.35f:1.65f;if(high)upper++;PrefabUtility.RecordPrefabInstancePropertyModifications(fixtures[i]);}}
 EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{upperMaintenanceFixtures=upper,totalAddedLights=0};}
}
